import{z as l,x as o,o as e,c as s,q as A,j as B,D as a,d as i,s as r,S as n}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"子单调度的深化","description":"","frontmatter":{"title":"子单调度的深化","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ex-slice-scheduling-deep.md","filePath":"quant/ex-slice-scheduling-deep.md","lastUpdated":1791413859000}'),d={name:"quant/ex-slice-scheduling-deep.md"};function p(h,E,_,c,u,F){const t=o("Mermaid");return e(),s("div",null,[E[2]||(E[2]=A('<h1 id="子单调度的深化" tabindex="-1">子单调度的深化 <a class="header-anchor" href="#子单调度的深化" aria-label="Permalink to &quot;子单调度的深化&quot;">​</a></h1><div class="epigraph"><p>日程给计划，调度给修正：执行的质量不在计划曲线多漂亮，而在偏差出现后，修正律以多快速度、多大冲击把它收敛掉。</p><footer>—— 据 Bertsimas and Lo, Dynamic Programming and Trade Execution, Journal of Financial Markets, 1998；Almgren and Chriss, Journal of Risk, 2000/2001 整理</footer></div><p><a href="/quant/ex-algo-taxonomy-deep">上一课</a>把算法收成五根轴，分化最大的是决策轴：静态日程只回答「这一秒该完成多少」，不回答「没完成怎么办」。主干 <a href="/quant/child-order-slicing">子单切片</a>定了量、间隔、类型三维，<a href="/quant/adaptive-pov">自适应 POV</a> 给过控制律样例；本课把子单调度写成闭环控制：状态怎么取、增益怎么定、截止怎么守。不重推 AC 的双曲正弦。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>开环日程假设「目标即成交」。真实成交是随机的：限价片在队列里等 <a href="/quant/fill-probability">成交概率</a>，市价片吃到的深度随盘口变，涨跌停与临停直接中断释放。累计成交于是随机偏离计划，记进度误差 \\(e_t=\\hat q_t-q_t\\)（计划量减已成交量）。\\(e_t\\) 不被处理，就滚成两种尾部：一路落后，余量压到窗口末端，在最差的流动性里集中清扫；一路领先，为抢进度在清淡时段重复吃簿。问题是设计修正律，使完成风险有界，而修正本身不再制造新冲击。</p><p>误差从哪来决定怎么修。队列等待造成的落后是慢变量，可匀速追回；盘口瞬间变厚造成的领先是快变量，追它会放大参与率。两类混进同一增益，算法在快噪声上振荡。</p><p><span class="marginnote">进度误差就是「计划减已成交」的欠账：计划到此刻应完成 60%，实际只成交 55%，误差就是 5% 的欠账。开环日程对这笔欠账视而不见，闭环调度把欠账本身当成输入信号，用来修正下一片的量。</span></p>',7)),(e(),B(n,null,{default:a(()=>[r(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20ERR%5B%22%E8%BF%9B%E5%BA%A6%E8%AF%AF%E5%B7%AE%20e_t%20%E5%81%8F%E7%A6%BB%E9%9B%B6%E7%82%B9%22%5D%20--%3E%20DIR%7B%22%E5%81%8F%E7%A6%BB%E6%96%B9%E5%90%91%3F%22%7D%0A%20%20DIR%20--%3E%7C%22%E8%90%BD%E5%90%8E%22%7C%20SLOW%5B%22%E6%85%A2%E5%8F%98%E9%87%8F%3A%20%E9%98%9F%E5%88%97%E7%AD%89%E5%BE%85%E6%88%90%E4%BA%A4%22%5D%0A%20%20DIR%20--%3E%7C%22%E9%A2%86%E5%85%88%22%7C%20FAST%5B%22%E5%BF%AB%E5%8F%98%E9%87%8F%3A%20%E7%9B%98%E5%8F%A3%E7%9E%AC%E9%97%B4%E5%8F%98%E5%8E%9A%22%5D%0A%20%20SLOW%20--%3E%20FIX%5B%22%E5%8C%80%E9%80%9F%E8%BF%BD%E5%9B%9E%3A%20%E5%9C%A8%E5%A4%9A%E4%B8%AA%E7%89%87%E9%97%B4%E9%9A%94%E5%86%85%E6%8A%AC%E5%8D%87%E5%8F%82%E4%B8%8E%E7%8E%87%22%5D%0A%20%20FIX%20--%3E%20NEG%5B%22%E6%94%BE%E4%BB%BB%E7%9A%84%E4%BB%A3%E4%BB%B7%3A%20%E4%BD%99%E9%87%8F%E5%8E%8B%E5%88%B0%E7%AA%97%E5%8F%A3%E6%9C%AB%E7%AB%AF%2C%20%E5%9C%A8%E6%9C%80%E5%B7%AE%E6%B5%81%E5%8A%A8%E6%80%A7%E9%9B%86%E4%B8%AD%E6%B8%85%E6%89%AB%22%5D%0A%20%20FAST%20--%3E%20CUT%5B%22%E7%AB%8B%E5%8D%B3%E5%87%8F%E9%80%9F%2C%20%E5%90%A6%E5%88%99%E5%8F%82%E4%B8%8E%E7%8E%87%E5%9C%A8%E5%BF%AB%E5%99%AA%E5%A3%B0%E4%B8%8A%E6%8C%AF%E8%8D%A1%22%5D%0A%20%20CUT%20--%3E%20SYNC%5B%22%E6%94%BE%E5%A4%A7%E5%86%B2%E5%87%BB%3A%20%E4%B8%BA%E6%8A%A2%E8%BF%9B%E5%BA%A6%E5%9C%A8%E6%B8%85%E6%B7%A1%E6%97%B6%E6%AE%B5%E9%87%8D%E5%A4%8D%E5%90%83%E7%B0%BF%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[i(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h3 id="状态、时钟与控制律" tabindex="-1">状态、时钟与控制律 <a class="header-anchor" href="#状态、时钟与控制律" aria-label="Permalink to &quot;状态、时钟与控制律&quot;">​</a></h3><p>状态三元组：剩余库存 \\(x_t\\)、剩余时间 \\(T-t\\)、进度误差 \\(e_t\\)；外生状态：价差、波动、毒性。时钟可选墙上时钟、成交量时钟或风险时钟：成交量时钟把随机性对齐到流动性厚的时段，进度方差更小，见 <a href="/quant/intraday-seasonality">日内季节性</a>。控制律写成参与率修正：</p> \\[\\rho_t=\\mathrm{clip}\\Bigl(\\rho_0\\bigl(1+g\\,\\tfrac{e_t}{x_t}\\bigr),\\rho_{\\min},\\rho_{\\max}\\Bigr), \\]<p>落后为正则加速，领先为负则减速。增益 \\(g\\) 应相对成交动力学定标：一次修正要在若干个片间隔内显效，而不是在每笔成交后反弹。毒性门控叠在外层：<a href="/quant/ofi-toxicity">订单流毒性</a>升高时先压 \\(\\rho_{\\max}\\)，再谈追进度。</p><p><span class="marginnote">截止前收敛应预先编排：例如「完成八成不晚于八成时间」，剩余两成留给正常流动性，而不是全数压给尾盘。末端清扫在 TCA 尾部分位上的尖刺，几乎总对应一次失控的 \\(e_t\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>落地为三个模块。观测：成交回报与时钟对齐，\\(e_t\\) 用短窗平滑（EWMA），避免把部分成交的抖动当趋势。决策：控制律加硬规则——临近竞价段或收盘前 \\(\\Delta\\)，切换到 deadline 策略：剩余量转入 <a href="/quant/ex-auction-execution">竞价配额</a>，或按参与率上限线性排空，事先写死。执行：每片仍走 <a href="/quant/child-order-slicing">子单切片</a> 的三维规格，调度只改片的量与间隔，使归因时「日程」与「接口」可分离。</p><p>增益用回放数据扫描定标：\\(g\\) 过小等价开环，尾部照旧；过大则参与率在均值附近振荡。合适的 \\(g\\) 使 \\(e_t\\) 的自相关在几个片间隔内衰减，修正量的右尾不聚集在放量突发段。</p><p><span class="marginnote">增益 \\(g\\) 可以类比淋浴水温旋钮的灵敏度：\\(g\\) 太小像锈死的旋钮，水凉了半天没反应，等于开环；\\(g\\) 太大则一点误差就猛调，水温来回振荡。合用的 \\(g\\) 让欠账在几个片间隔内还清，而不是每笔成交后都反弹一次。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>反馈回路的失效方式可预测。其一，滞后振荡：回报延迟叠加增益过大形成极限环——加速、冲击、落后、再加速。其二，同步化：同批跑同类控制律的账户在价差恢复时一起加速，外生成交量假设失效，见 <a href="/quant/adaptive-pov">自适应 POV</a> 的结尾讨论；对策是增益与片间隔带随机化，代价是进度方差。其三，目标污染：KPI 若是贴 VWAP，控制律退化成追踪器；调度必须挂在到达价或完成率上。</p><p>不用滚动最优控制代替规则表，是因为最优控制需要条件冲击与波动的在线估计，误差进入二阶项，规则表是显式可审计的次优。折衷是分层：低频层重估 \\(\\rho_0\\) 与上下限，高频层只跑修正律，两层分开审计。</p>',12)),(e(),B(n,null,{default:a(()=>[r(t,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20PLAN%5B%22%E5%BC%80%E7%8E%AF%E6%97%A5%E7%A8%8B%20q_target%22%5D%20--%3E%20CMP%7B%22%E6%AF%94%E8%BE%83%E5%AE%9E%E7%8E%B0%E6%88%90%E4%BA%A4%22%7D%0A%20%20FILL%5B%22%E6%88%90%E4%BA%A4%E5%9B%9E%E6%8A%A5%22%5D%20--%3E%20CMP%0A%20%20CMP%20--%3E%20E%5B%22%E8%BF%9B%E5%BA%A6%E8%AF%AF%E5%B7%AE%20e_t%20(EWMA)%22%5D%0A%20%20E%20--%3E%20G%7B%22%E6%AF%92%E6%80%A7%E9%97%A8%E6%8E%A7%22%7D%0A%20%20TOX%5B%22%E4%BB%B7%E5%B7%AE%20%2F%20OFI%20%E7%8A%B6%E6%80%81%22%5D%20--%3E%20G%0A%20%20G%20--%3E%20RHO%5B%22%E4%BF%AE%E6%AD%A3%E5%8F%82%E4%B8%8E%E7%8E%87%20%CF%81_t%22%5D%0A%20%20RHO%20--%3E%20CLK%7B%22%E6%8E%A5%E8%BF%91%E6%88%AA%E6%AD%A2%3F%22%7D%0A%20%20CLK%20--%3E%7C%E5%90%A6%7C%20SLICE%5B%22%E4%B8%8B%E4%B8%80%E6%89%B9%E5%AD%90%E5%8D%95%22%5D%0A%20%20CLK%20--%3E%7C%E6%98%AF%7C%20DL%5B%22deadline%20%E7%AD%96%E7%95%A5%3A%20%E7%AB%9E%E4%BB%B7%E9%85%8D%E9%A2%9D%E6%88%96%E7%BA%BF%E6%80%A7%E6%8E%92%E7%A9%BA%22%5D%0A%20%20SLICE%20--%3E%20FILL%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[i(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>控制律假设误差可观测：成交回报延迟、暗池成交的打印滞后都会让 \\(e_t\\) 偏大，落后被高估。填成概率模型在体制切换时失效，增益在恐慌日应预置收紧而非重估。A 股 9:20 后不可撤与 14:57 收盘竞价是硬截止，控制律须在节点前冻结。不要把归因残差拿去每日重估增益：参数按预登记节奏更新，否则调度层会把样本噪声写成规则。</p><p><span class="marginnote">初学者容易把 TCA 报告里尾盘集中放量的大单解读为「尾盘流动性好」，实际上那多半是进度误差一路落后、被控制律压到窗口末端的集中清扫——在最差的时点干了最多的活，冲击成本也最贵。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>调度是闭环控制：状态取剩余库存、剩余时间与平滑后的进度误差，输出参与率修正而非重画日程。</li><li>时钟选成交量轴可降低进度方差；增益过小退化为开环，过大在自身冲击上振荡。</li><li>毒性门控外置：先压上限再追进度；末端清扫是失控误差的标志。</li><li>反馈的三种失效——滞后振荡、同批同步化、基准污染——对策都抬高进度方差。</li><li>低频重估参数、高频只跑修正律，两层分开审计；硬截止节点前冻结。</li><li>出处：Bertsimas and Lo, <em>Journal of Financial Markets</em>, 1998；Almgren and Chriss, <em>Journal of Risk</em>, 2000/2001；切片三维见 <a href="/quant/child-order-slicing">子单切片</a>。</li></ul>',5))])}const C=l(d,[["render",p]]);export{D as __pageData,C as default};
